+func normalizeMemoryLoopPrompt(prompt string) (string, bool) {
+	cleaned := textutil.StripIDEContextTags(prompt)
+	if cleaned == "" {
+		return "", false
+	}
+	if isMemoryLoopInternalPrompt(cleaned) {
+		return "", false
+	}
+	return cleaned, true
+}
