+func isMemoryLoopInternalPrompt(prompt string) bool {
+	trimmed := strings.ToLower(strings.TrimSpace(prompt))
+	return strings.HasPrefix(trimmed, "<task>") ||
+		strings.HasPrefix(trimmed, "<task-notification>")
